import {Chess} from './vendor/chess.js';
const $=id=>document.getElementById(id), glyph={wk:'♔',wq:'♕',wr:'♖',wb:'♗',wn:'♘',wp:'♙',bk:'♚',bq:'♛',br:'♜',bb:'♝',bn:'♞',bp:'♟'};
let game=new Chess(), editing=false, draft={}, tool='wq', selected=null, flipped=false, playing=false, busy=false, ready=false, suggestion=null, worker, searchFen='', purpose='analyze';
function say(t){$('message').textContent=t;}
function mapBoard(){const m={};for(const row of game.board())for(const p of row)if(p)m[p.square]=p.color+p.type;return m;}
function render(){const m=editing?draft:mapBoard(),files=flipped?'hgfedcba':'abcdefgh',ranks=flipped?'12345678':'87654321';let targets=[];if(selected&&!editing)targets=game.moves({square:selected,verbose:true}).map(x=>x.to);$('board').replaceChildren();for(const rank of ranks)for(const file of files){const sq=file+rank,p=m[sq],b=document.createElement('button');b.className='square'+(((file.charCodeAt(0)-97+Number(rank))%2===0)?' dark':'')+(p?.[0]==='w'?' white-piece':'')+(selected===sq?' selected':'')+(targets.includes(sq)?' target':'')+(suggestion&&[suggestion.slice(0,2),suggestion.slice(2,4)].includes(sq)?' best':'');b.textContent=glyph[p]||'';b.setAttribute('aria-label',`${sq}${p?' '+(p[0]==='w'?'white':'black')+' '+({k:'king',q:'queen',r:'rook',b:'bishop',n:'knight',p:'pawn'}[p[1]]):' empty'}`);if(file===files[0]){const c=document.createElement('span');c.className='coord';c.textContent=rank;b.append(c);}if(rank===ranks[7]){const c=document.createElement('span');c.className='coord file';c.textContent=file;b.append(c);}b.onclick=()=>clickSquare(sq);$('board').append(b);} $('turnText').textContent=editing?'Place your pieces':(game.turn()==='w'?'White':'Black')+' to move'+(game.isCheckmate()?' · Checkmate':game.isStalemate()?' · Stalemate':game.isDraw()?' · Draw':game.isCheck()?' · Check':'');$('modeText').textContent=editing?'Position editor':playing?'Playing Stockfish':'Analysis mode';$('fen').value=editing?draftFen():game.fen();$('editor').hidden=!editing;$('stop').hidden=!playing;$('play').hidden=playing;$('analyze').disabled=!ready||busy||editing||game.isGameOver();$('apply').disabled=busy||editing||!suggestion;$('human').disabled=busy;$('edit').textContent=editing?'Cancel editing':'Edit position';for(const id of ['undo','reset','edit','load','play','stop'])$(id).disabled=busy;$('history').textContent=game.history().map((m,i)=>(i%2===0?`${Math.floor(i/2)+1}. `:'')+m).join(' ');}
function clearResult(){suggestion=null;$('best').textContent='Find your next move';$('eval').textContent='—';$('line').textContent='Ask Stockfish to examine the current position.';}
function validatePosition(g){const pieces=g.board().flat().filter(Boolean);for(const color of ['w','b']){const ps=pieces.filter(p=>p.color===color);if(ps.length>16||ps.filter(p=>p.type==='p').length>8)throw Error('Each side can have at most 16 pieces and 8 pawns.');}const other=g.turn()==='w'?'b':'w',king=pieces.find(p=>p.color===other&&p.type==='k');if(g.isAttacked(king.square,g.turn()))throw Error('The side that just moved cannot leave its own king in check. Change whose turn it is or move the attacking piece.');const [board,turn,rights,ep]=g.fen().split(' '),m={};for(const p of pieces)m[p.square]=p.color+p.type;for(const [right,k,r] of [['K','e1','h1'],['Q','e1','a1'],['k','e8','h8'],['q','e8','a8']])if(rights.includes(right)&&(m[k]!== (right===right.toUpperCase()?'wk':'bk')||m[r]!== (right===right.toUpperCase()?'wr':'br')))throw Error('Castling rights require the king and rook on their original squares.');if(ep!=='-'){const c=turn==='w'?'bp':'wp',rank=turn==='w'?'5':'4';if(m[ep[0]+rank]!==c||m[ep])throw Error('The en passant square does not match a pawn that just moved two squares.');}return g;}
function draftFen(){let rows=[];for(let r=8;r>=1;r--){let row='',n=0;for(const f of 'abcdefgh'){const p=draft[f+r];if(!p)n++;else{if(n)row+=n;n=0;row+=p[0]==='w'?p[1].toUpperCase():p[1];}}if(n)row+=n;rows.push(row);}const rights=[...document.querySelectorAll('.rights input:checked')].map(x=>x.value).join('')||'-';return `${rows.join('/')} ${$('side').value} ${rights} - 0 1`;}
function clickSquare(sq){if(busy)return;if(editing){if(tool==='erase')delete draft[sq];else {if(tool[1]==='k')for(const key in draft)if(draft[key]===tool)delete draft[key];draft[sq]=tool;}render();return;}if(playing&&game.turn()!==$('human').value)return;if(selected&&selected!==sq){const options=game.moves({square:selected,verbose:true}).filter(m=>m.to===sq);if(options.length){let promotion='q';if(options.some(x=>x.promotion)){const answer=prompt('Promote to: q = queen, r = rook, b = bishop, n = knight','q');if(answer===null)return;promotion=answer.toLowerCase();if(!['q','r','b','n'].includes(promotion)){say('Choose q, r, b, or n for promotion.');return;}}game.move({from:selected,to:sq,promotion});selected=null;clearResult();render();afterMove();return;}}selected=game.get(sq)?.color===game.turn()?sq:null;render();}
function afterMove(){say(game.isGameOver()?'The game has ended. Undo a move or edit the position to continue.':'Click a piece, then a highlighted square to move it.');if(playing&&!game.isGameOver()&&game.turn()!==$('human').value)search('play');}
function search(type){if(!ready||busy||editing||game.isGameOver())return;try{validatePosition(game);}catch(e){say(e.message);return;}busy=true;purpose=type;searchFen=game.fen();suggestion=null;selected=null;$('best').textContent='Thinking…';$('line').textContent='Stockfish is exploring legal continuations.';render();worker.postMessage('position fen '+searchFen);worker.postMessage('go movetime '+$('time').value);}
function startEngine(){worker=new Worker('./vendor/stockfish-19-lite-single.js');const timer=setTimeout(()=>{if(!ready){$('engine').textContent='Engine taking longer to load';say('Stockfish is still loading. If this persists, refresh or try a browser with WebAssembly support.');}},20000);worker.onerror=()=>{clearTimeout(timer);ready=false;busy=false;$('engine').textContent='Stockfish unavailable';say('Could not load Stockfish. Refresh the page or run the app using npm start rather than opening the HTML file directly.');render();};worker.onmessage=({data})=>{for(const line of String(data).split('\n')){if(line==='uciok'){worker.postMessage('setoption name Hash value 32');worker.postMessage('isready');}if(line==='readyok'){clearTimeout(timer);ready=true;$('engine').textContent='Stockfish 19 · Ready';render();}if(line.startsWith('info ')&&busy){const depth=line.match(/\bdepth (\d+)/),score=line.match(/\bscore (cp|mate) (-?\d+)/),pv=line.match(/\bpv (.+)/);if(depth)$('depth').textContent=`Depth ${depth[1]} · Evaluation from White’s side`;if(score){const v=Number(score[2])*(game.turn()==='w'?1:-1);$('eval').textContent=score[1]==='mate'?`Mate ${v}`:(v>=0?'+':'')+(v/100).toFixed(2);}if(pv){const clone=new Chess(searchFen),moves=[];for(const u of pv[1].trim().split(' ').slice(0,7))try{moves.push(clone.move({from:u.slice(0,2),to:u.slice(2,4),promotion:u[4]}).san);}catch{break;}$('line').textContent=moves.join('  ');}}if(line.startsWith('bestmove ')&&busy){busy=false;const u=line.split(' ')[1];if(u==='(none)'||u==='0000'){say('There are no legal moves in this position.');render();return;}suggestion=u;const clone=new Chess(searchFen);try{const m=clone.move({from:u.slice(0,2),to:u.slice(2,4),promotion:u[4]});$('best').textContent=m.san;say(`Best move: ${m.san} (${m.from} to ${m.to}).`);if(purpose==='play')apply();else render();}catch{say('The engine returned an invalid move. Try again.');clearResult();render();}}}};worker.postMessage('uci');}
function apply(){if(!suggestion||busy)return;game.move({from:suggestion.slice(0,2),to:suggestion.slice(2,4),promotion:suggestion[4]});clearResult();selected=null;render();afterMove();}
$('analyze').onclick=()=>search('analyze');$('apply').onclick=apply;$('flip').onclick=()=>{flipped=!flipped;render();};$('reset').onclick=()=>{game=new Chess();editing=false;playing=false;selected=null;clearResult();render();say('Starting position loaded.');};$('undo').onclick=()=>{if(editing)return;game.undo();if(playing&&game.turn()!==$('human').value)game.undo();selected=null;clearResult();render();say('Move undone.');};$('edit').onclick=()=>{if(!editing){draft=mapBoard();$('side').value=game.turn();const rights=game.fen().split(' ')[2];document.querySelectorAll('.rights input').forEach(x=>x.checked=rights.includes(x.value));playing=false;}editing=!editing;selected=null;clearResult();render();say(editing?'Select a piece below the analysis panel, then click a square.':'Position editing canceled.');};$('clear').onclick=()=>{draft={};document.querySelectorAll('.rights input').forEach(x=>x.checked=false);render();};$('finish').onclick=()=>{try{game=validatePosition(new Chess(draftFen()));editing=false;clearResult();render();say('Your position is ready. Find the best move or play against Stockfish.');}catch(e){say('Position needs a change: '+e.message);}};$('side').onchange=render;document.querySelectorAll('.rights input').forEach(x=>x.onchange=render);$('load').onclick=()=>{try{const next=validatePosition(new Chess($('fen').value.trim()));game=next;editing=false;playing=false;selected=null;clearResult();render();say('Position loaded.');}catch(e){say('Could not load position: '+e.message);}};$('copy').onclick=async()=>{try{await navigator.clipboard.writeText($('fen').value);say('FEN copied.');}catch{ $('fen').select();say('Select and copy the FEN text manually.');}};$('play').onclick=()=>{if(editing){say('Click “Use this position” first.');return;}if(!ready){say('Wait for Stockfish to finish loading.');return;}if(game.isGameOver()){say('This position has already ended. Edit it to start a game.');return;}playing=true;render();afterMove();};$('stop').onclick=()=>{playing=false;render();say('Analysis mode. You can move either side.');};$('human').onchange=()=>{if(playing&&!busy)afterMove();};for(const p of [...Object.keys(glyph),'erase']){const b=document.createElement('button');b.textContent=glyph[p]||'⌫';b.title=p==='erase'?'Eraser':p;b.setAttribute('aria-label',p==='erase'?'Eraser':(p[0]==='w'?'White ':'Black ')+({k:'king',q:'queen',r:'rook',b:'bishop',n:'knight',p:'pawn'}[p[1]]));b.className=p===tool?'chosen':'';b.onclick=()=>{tool=p;document.querySelectorAll('#palette button').forEach(x=>x.classList.remove('chosen'));b.classList.add('chosen');};$('palette').append(b);}render();startEngine();
